7px}.document-row{margin-top:13px;padding:14px;display:grid;grid-template-columns:auto 1fr auto;gap:10px;align-items:center;border:1px dashed #27547a;border-radius:10px;color:#00e5ff}.document-row.complete{color:#24d89a;border-style:solid}.document-row span{display:grid}.document-row b{color:#f5f8ff;font-size:9px}.document-row small{margin-top:3px;color:#718096;font-size:7px}.document-row button{padding:7px 9px;border:1px solid currentColor;border-radius:7px;color:inherit;background:transparent;cursor:pointer;font-size:7px}.media-grid{margin-bottom:17px;display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.media-grid>div,.media-add{position:relative;overflow:hidden;aspect-ratio:16/10;border:1px solid #183352;border-radius:9px;background:#071225}.media-grid img{width:100%;height:100%;object-fit:cover}.media-grid div>span{position:absolute;right:6px;bottom:6px;left:6px;padding:5px;border-radius:5px;background:rgb(2 4 13/.78);font-size:7px}.media-grid div>button{position:absolute;top:6px;right:6px;width:24px;height:24px;border:1px solid #3b4a65;border-radius:6px;color:#f5f8ff;background:rgb(2 4 13/.8);cursor:pointer}.media-add{display:grid;place-items:center;align-content:center;gap:6px;border-style:dashed;color:#00e5ff;cursor:pointer}.media-add span{font-size:8px;font-weight:800}.media-add small{color:#718096;font-size:7px}.tip{margin-top:14px;padding:14px;display:flex;gap:10px;border:1px solid #2d3d66;border-radius:10px;color:#8b5cf6;background:rgb(139 92 246/.06)}.tip span{display:grid}.tip b{color:#f5f8ff;font-size:9px}.tip small{margin-top:3px;color:#8d9bb1;font-size:7px;line-height:1.5}.licence-grid{display:grid;grid-template-columns:1fr 1fr;gap:11px}.licence{padding:16px;border:1px solid #183352;border-radius:11px;background:#071225}.licence>div:first-child{display:flex;gap:9px;color:#00e5ff}.licence>div:first-child span{display:grid}.licence>div:first-child b{color:#f5f8ff;font-size:10px}.licence>div:first-child small{margin-top:3px;color:#718096;font-size:7px;line-height:1.4}.money{margin-top:14px;display:flex;align-items:center;border:1px solid #27547a;border-radius:9px;background:#030711}.money b{padding-left:12px;color:#00e5ff}.money input{border:0;background:transparent;font-size:22px;font-weight:850}.licence>em{margin-top:7px;color:#24d89a;font-size:7px;font-style:normal}.market-benchmark{margin:15px 0;padding:15px;display:grid;grid-template-columns:repeat(4,1fr);border:1px solid #183352;border-radius:10px;background:#050a16}.market-benchmark div{display:grid}.market-benchmark div+div{padding-left:13px;border-left:1px solid #183352}.market-benchmark span{color:#718096;font-size:7px}.market-benchmark b,.market-benchmark strong{margin-top:3px;font-size:12px}.market-benchmark strong{color:#24d89a}.free-option{padding:14px;grid-template-columns:auto 1fr!important;align-items:start;border:1px solid #183352;border-radius:10px}.free-option input{width:auto;min-height:auto;margin-top:3px;accent-color:#00e5ff}.free-option span{display:grid}.free-option b{color:#f5f8ff;font-size:9px}.free-option small{margin-top:3px}.review-card{padding:13px;display:grid;grid-template-columns:230px 1fr;gap:15px;border:1px solid #27547a;border-radius:12px;background:#050a16}.review-card>img{width:100%;height:155px;object-fit:cover;border-radius:8px}.review-card>div>span{color:#00e5ff;font-size:8px}.review-card h2{margin:8px 0 6px}.review-card p{color:#aab5c8;font-size:9px;line-height:1.55}.review-card>div>div{display:flex;align-items:baseline;gap:9px}.review-card>div>div b{font-size:22px}.review-card>div>div small{color:#718096;font-size:7px}.checklist{margin:14px 0}.checklist>div{min-height:39px;padding:0 10px;display:grid;grid-template-columns:auto 1fr auto;gap:9px;align-items:center;border-top:1px solid #122a43;color:#ffb547;font-size:8px}.checklist>div.done{color:#24d89a}.checklist span{color:#aab5c8}.checklist b{font-size:7px}.agreement{padding:14px;grid-template-columns:auto 1fr!important;align-items:start!important;border:1px solid #27547a;border-radius:10px;line-height:1.55}.agreement input{width:auto;min-height:auto;margin-top:3px;accent-color:#00e5ff}.review-actions{margin-top:14px;display:flex;justify-content:flex-end;gap:8px}.button:disabled{opacity:.45;cursor:not-allowed;transform:none}.footer-actions{margin-top:12px;display:flex;justify-content:space-between}.upload-grid aside{display:grid;gap:12px}.ring{width:92px;height:92px;margin:18px auto 10px;display:grid;place-items:center;align-content:center;border:7px solid #142b45;border-top-color:#00e5ff;border-right-color:#8b5cf6;border-radius:50%}.ring b{font-size:24px}.ring small{color:#718096;font-size:7px}.progress-card h3{text-align:center}.progress-card>p{text-align:center;color:#718096;font-size:8px;line-height:1.5}.progress-card>button{width:100%;min-height:38px;padding:0 8px;display:grid;grid-template-columns:24px 1fr;gap:8px;align-items:center;border:0;border-top:1px solid #122a43;color:#718096;background:transparent;cursor:pointer;text-align:left;font-size:8px}.progress-card>button i{width:21px;height:21px;display:grid;place-items:center;border:1px solid currentColor;border-radius:50%;font-size:7px;font-style:normal}.progress-card>button.done{color:#24d89a}.progress-card>button.active span{color:#00e5ff}.help{color:#00e5ff}.help h3{color:#f5f8ff}.help p{color:#718096;font-size:8px;line-height:1.5}.help button{width:100%;min-height:36px;border:1px solid #27547a;border-radius:8px;color:#00e5ff;background:#071225;cursor:pointer;font-size:8px}
  @media(max-width:980px){.upload-grid{grid-template-columns:1fr}.upload-grid aside{grid-template-columns:1fr 1fr}.stepper{grid-template-columns:repeat(5,150px);overflow-x:auto}}
  @media(max-width:650px){.upload-head{grid-template-columns:1fr}.upload-head .button{width:100%}.two,.licence-grid,.market-benchmark,.media-grid{grid-template-columns:1fr}.review-card{grid-template-columns:1fr}.upload-grid aside{grid-template-columns:1fr}.review-actions,.footer-actions{display:grid}.review-actions .button,.footer-actions .button{width:100%}}
</style>
